import json, hashlib
from pathlib import Path
man = json.load(open('dataset/manifest.json'))
cat = json.load(open('dataset/catalog.json'))
root = Path('dataset')
difficulties = {}
for r in man['rows']:
    difficulties.setdefault(r['difficulty'], []).append(r)
for d, rows in sorted(difficulties.items()):
    paths = set(r['path'].split('/')[0] + '/' + r['path'].split('/')[1] for r in rows)
    print(d, len(rows), 'path prefixes:', paths)
print()
# check catalog == manifest
same = cat['rows'] == man['rows']
print('catalog rows == manifest rows:', same)
# check file existence and sha
missing, mismatch, ok = [], [], 0
for r in man['rows']:
    p = root / r['path']
    if not p.is_file():
        missing.append(r['path'])
    else:
        h = hashlib.sha256(p.read_bytes()).hexdigest()
        if h == r['sha256']:
            ok += 1
        else:
            mismatch.append((r['path'], r['sha256'], h))
print('ok:', ok, 'missing:', len(missing), 'mismatch:', len(mismatch))
for m in missing[:10]: print('MISSING', m)
for m in mismatch[:10]: print('MISMATCH', m)
"

